from garmin_personal_api import GarminPersonalApiClient, PersonalApiAuthenticator

from health_oracle import (
    METRICS,
    _fetch_datasets,
    _format_value,
    _load_api_key,
    _select_series,
    _walk_numeric_fields,
)


METRIC_SOURCES = {
    "hrv": "hrv",
    "sleep": "sleep",
    "sleepScore": "sleep_score",
    "restingHeartRate": "heart_rate",
    "stress": "stress",
    "bodyBattery": "body_battery",
}

WATCH_DIRECTIONS = {
    "hrv": "below",
    "sleep": "below",
    "sleepScore": "below",
    "restingHeartRate": "above",
    "stress": "above",
    "bodyBattery": "below",
}
MINIMUM_BASELINE_DAYS = 14
TRAINING_VOLUME_SPIKE_RATIO = 2.0


def build_metric_payload(
    key: str,
    values_by_field: dict[str, dict[date, float]],
    failed_sources: dict[str, str],
    start_date: date,
    end_date: date,
    native_hrv_payload: object | None = None,
) -> dict[str, Any]:
    """Build one UI-safe metric record from normalized dated measurements."""
    source_key = METRIC_SOURCES[key]
    spec = METRICS[source_key]
    selected = _select_series(values_by_field, spec)
    metric: dict[str, Any] = {
        "label": "Resting heart rate" if key == "restingHeartRate" else spec.label,
        "unit": spec.unit,
        "field": None,
        "points": [],
        "latest": None,
        "baseline7": None,
        "baseline28": None,
        "usualRange28": None,
        "rangeLabel": "Prior 28-day personal range",
        "garminStatus": None,
        "status": "unavailable",
        "availableDays": 0,
        "unavailableReason": None,
    }

    if selected is None:
        if source_key in failed_sources:
            metric["unavailableReason"] = "Garmin could not return this data right now."
        else:
            metric["unavailableReason"] = "No matching measurements were returned for this period."
        return metric

    field, source_values = selected
    readings = sorted(
        (reading_date, value)
        for reading_date, value in source_values.items()
        if start_date <= reading_date <= end_date
    )
    if not readings:
        metric["unavailableReason"] = "No dated measurements were returned for this period."
        return metric

    points = []
    for reading_date, value in readings:
        display_value, unit = _format_value(value, field, spec)
        points.append({"date": reading_date.isoformat(), "value": round(display_value, 2)})

    metric["field"] = field
    metric["unit"] = "score" if source_key == "stress" else unit
    metric["points"] = points
    metric["latest"] = points[-1]
    metric["availableDays"] = len(points)

    latest_date = readings[-1][0]
    baseline_end = latest_date - timedelta(days=1)
    baseline_start = baseline_end - timedelta(days=27)
    baseline_readings = [
        (reading_date, value)
        for reading_date, value in readings
        if baseline_start <= reading_date <= baseline_end
    ]
    week_start = latest_date - timedelta(days=7)
    recent_week = [value for reading_date, value in readings if week_start <= reading_date < latest_date]

    if len(recent_week) >= 4:
        metric["baseline7"] = round(mean(_display_values(recent_week, field, spec)), 2)
    if len(baseline_readings) >= MINIMUM_BASELINE_DAYS:
        baseline_values = _display_values([value for _, value in baseline_readings], field, spec)
        range_low = _percentile(baseline_values, 0.1)
        range_high = _percentile(baseline_values, 0.9)
        latest_value = points[-1]["value"]
        metric["baseline28"] = round(median(baseline_values), 2)
        metric["usualRange28"] = [round(range_low, 2), round(range_high, 2)]
        if latest_value < range_low:
            metric["status"] = "below_usual"
        elif latest_value > range_high:
            metric["status"] = "above_usual"
        else:
            metric["status"] = "within_usual"
    else:
        metric["status"] = "insufficient_history"

    if key == "hrv":
        native_baseline = _find_native_hrv_baseline(native_hrv_payload, latest_date)
        if native_baseline is not None:
            balanced_low, balanced_upper, garmin_status = native_baseline
            metric["usualRange28"] = [balanced_low, balanced_upper]
            metric["rangeLabel"] = "Garmin balanced range"
            metric["garminStatus"] = garmin_status
            latest_value = points[-1]["value"]
            if latest_value < balanced_low:
                metric["status"] = "below_usual"
            elif latest_value > balanced_upper:
                metric["status"] = "above_usual"
            else:
                metric["status"] = "within_usual"

    return metric


def _find_native_hrv_baseline(
    payload: object | None,
    target_date: date,
) -> tuple[float, float, str | None] | None:
    """Read Garmin's HRV balanced bounds for the latest date when present."""
    if not isinstance(payload, dict):
        return None
    summaries = payload.get("hrvSummaries")
    if not isinstance(summaries, list):
        return None
    for summary in summaries:
        if not isinstance(summary, dict) or summary.get("calendarDate") != target_date.isoformat():
            continue
        baseline = summary.get("baseline")
        if not isinstance(baseline, dict):
            return None
        low = baseline.get("balancedLow")
        high = baseline.get("balancedUpper")
        if isinstance(low, (int, float)) and isinstance(high, (int, float)):
            status = summary.get("status")
            return float(low), float(high), status if isinstance(status, str) else None
    return None


def _display_values(values: list[float], field: str, spec: Any) -> list[float]:
    """Convert a sequence using the same unit conversion as individual readings."""
    return [_format_value(value, field, spec)[0] for value in values]


def _percentile(values: list[float], fraction: float) -> float:
    """Linearly interpolate a percentile from an ordered sample."""
    ordered = sorted(values)
    position = (len(ordered) - 1) * fraction
    lower_index = int(position)
    upper_index = min(lower_index + 1, len(ordered) - 1)
    weight = position - lower_index
    return ordered[lower_index] * (1 - weight) + ordered[upper_index] * weight


def build_training_briefing(
    metrics: dict[str, dict[str, Any]],
    training_context: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Create a conservative training approach from deviations versus prior personal ranges."""
    recovery_metrics = {key: metrics[key] for key in WATCH_DIRECTIONS if key in metrics}
    ready_metrics = [
        key for key, metric in recovery_metrics.items()
        if metric["status"] in {"within_usual", "below_usual", "above_usual"}
    ]
    outside_range = [
        key for key, metric in recovery_metrics.items()
        if metric["status"] in {"below_usual", "above_usual"}
    ]
    flags = [
        key for key, metric in recovery_metrics.items()
        if metric["status"] == f"{WATCH_DIRECTIONS[key]}_usual"
    ]
    volume_flag = bool(training_context and training_context.get("volumeStatus") == "well_above_recent")
    evidence = [
        {
            "metric": recovery_metrics[key]["label"],
            "direction": "below" if recovery_metrics[key]["status"] == "below_usual" else "above",
            "isCaution": key in flags,
            "usualRange": recovery_metrics[key]["usualRange28"],
            "unit": recovery_metrics[key]["unit"],
        }
        for key in outside_range
    ]
    if volume_flag:
        evidence.append({
            "metric": "Weekly activity duration",
            "direction": "above",
            "isCaution": True,
            "usualRange": None,
            "unit": "minutes",
        })
    if len(ready_metrics) < 2:
        return {
            "approach": "Not enough recent history for a personalized suggestion.",
            "explanation": "There isn’t enough history to compare yet. Use how you feel today; a single reading cannot decide a workout.",
            "dataSufficiency": "Limited history",
            "evidence": evidence,
            "medicalDisclaimer": "This is general training context, not medical advice.",
        }

    if len(flags) + int(volume_flag) >= 2:
        approach = "Consider rest or an easy session today."
        explanation = "Several recovery or training-volume signals differ from your usual pattern. An easier session is a cautious option, not a diagnosis; if you feel unwell, rest and seek appropriate care."
    elif len(flags) == 1:
        approach = "Keep today flexible."
        explanation = f"{recovery_metrics[flags[0]]['label']} differs from your usual pattern. One signal alone doesn’t mean you must skip training; adjust intensity to how you feel."
    elif volume_flag:
        approach = "Consider an easy session or rest today."
        explanation = "Your recent training volume was much higher than usual. An easy session may help keep the day manageable, especially if you feel fatigued."
    elif outside_range:
        approach = "No training caution flagged."
        explanation = "Some measurements differ from your usual range, but a difference isn’t automatically a problem and doesn’t change today’s suggestion."
    else:
        approach = "Your recovery looks close to usual."
        explanation = "These readings are close to your recent personal ranges, not population scores. If you feel well, your planned session may be reasonable."

    return {
        "approach": approach,
        "explanation": explanation,
        "dataSufficiency": "Based on your recent personal ranges",
        "evidence": evidence,
        "medicalDisclaimer": "This is general training context, not medical advice.",
    }


def build_dashboard_payload(
    datasets: dict[str, dict[str, dict[date, float]]],
    failures: dict[str, str],
    start_date: date,
    end_date: date,
    training_context: dict[str, Any] | None = None,
    native_hrv_payload: object | None = None,
) -> dict[str, Any]:
    """Shape normalized Garmin records into dated metric series for the UI."""
    metrics = {
        key: build_metric_payload(
            key,
            datasets.get(source_key, {}),
            failures,
            start_date,
            end_date,
            native_hrv_payload if key == "hrv" else None,
        )
        for key, source_key in METRIC_SOURCES.items()
    }
    coverage_dates = {
        point["date"]
        for metric in metrics.values()
        for point in metric["points"]
    }
    return {
        "period": {"days": (end_date - start_date).days + 1, "startDate": start_date.isoformat(), "endDate": end_date.isoformat()},
        "metrics": metrics,
        "coverageDays": len(coverage_dates),
        "trainingContext": training_context or _empty_training_context(),
        "trainingBriefing": build_training_briefing(metrics, training_context),
    }


def _activity_date(record: dict[str, Any]) -> date | None:
    """Extract a calendar date from a Garmin activity summary without retaining its identity."""
    for field in ("startTimeLocal", "startTimeGMT"):
        value = record.get(field)
        if isinstance(value, str):
            try:
                return date.fromisoformat(value[:10])
            except ValueError:
                continue
    return None


def _fetch_activity_records(
    client: GarminPersonalApiClient,
    start_date: date,
    end_date: date,
) -> list[dict[str, Any]]:
    """Page through recent activity summaries, retaining records only in memory."""
    page_size = 20
    offset = 0
    records = []
    seen_ids = set()
    while offset < 400:
        payload = client.search_activities(
            start=offset,
            limit=page_size,
            start_date=start_date,
            end_date=end_date,
        )
        if not isinstance(payload, list):
            break
        for record in payload:
            if not isinstance(record, dict):
                continue
            activity_id = record.get("activityId")
            if activity_id is not None and activity_id in seen_ids:
                continue
            if activity_id is not None:
                seen_ids.add(activity_id)
            records.append(record)
        if len(payload) < page_size:
            break
        offset += len(payload)
    return records


def _empty_training_context(reason: str = "Activity history is unavailable.") -> dict[str, Any]:
    """Return an explicit unavailable activity context without inventing zero values."""
    return {
        "available": False,
        "unavailableReason": reason,
        "last7Days": None,
        "previous28DaysWeeklyAverageMinutes": None,
        "previous28DaysWeeklyAverageActivityLoad": None,
    }


def build_training_context(records: list[dict[str, Any]], end_date: date) -> dict[str, Any]:
    """Aggregate private activity summaries into recent training context."""
    measured_activities = []
    for record in records:
        activity_date = _activity_date(record)
        duration = record.get("duration")
        distance = record.get("distance")
        if activity_date is None or not isinstance(duration, (int, float)) or not isfinite(duration):
            continue
        distance_value = distance if isinstance(distance, (int, float)) and isfinite(distance) else None
        activity_load = record.get("activityTrainingLoad")
        activity_load_value = activity_load if isinstance(activity_load, (int, float)) and isfinite(activity_load) else None
        measured_activities.append((activity_date, float(duration), distance_value, activity_load_value))

    recent_start = end_date - timedelta(days=6)
    prior_end = end_date - timedelta(days=7)
    prior_start = end_date - timedelta(days=34)
    recent = [entry for entry in measured_activities if recent_start <= entry[0] <= end_date]
    prior = [entry for entry in measured_activities if prior_start <= entry[0] <= prior_end]
    recent_distances = [distance for _, _, distance, _ in recent if distance is not None]
    recent_loads = [load for _, _, _, load in recent if load is not None]
    prior_loads = [load for _, _, _, load in prior if load is not None]
    recent_duration_minutes = round(sum(duration for _, duration, _, _ in recent) / 60)
    previous_weekly_average = round(sum(duration for _, duration, _, _ in prior) / 60 / 4) if prior else None
    volume_status = (
        "well_above_recent"
        if previous_weekly_average and recent_duration_minutes > previous_weekly_average * TRAINING_VOLUME_SPIKE_RATIO
        else "not_flagged"
    )

    return {
        "available": True,
        "unavailableReason": None,
        "last7Days": {
            "activityCount": len(recent),
            "durationMinutes": recent_duration_minutes,
            "distanceKm": round(sum(recent_distances) / 1000, 1) if recent_distances else None,
            "activityTrainingLoad": round(sum(recent_loads), 1) if recent_loads else None,
        },
        "previous28DaysWeeklyAverageMinutes": previous_weekly_average,
        "previous28DaysWeeklyAverageActivityLoad": round(sum(prior_loads) / 4, 1) if prior_loads else None,
        "volumeStatus": volume_status,
    }


def _numeric_snapshot(
    label: str,
    scope: str,
    payload: object,
    field_labels: dict[str, tuple[str, str]],
) -> dict[str, Any]:
    """Select named numeric fields from a latest-day API response."""
    fields = {}
    for _, path, value in _walk_numeric_fields(payload):
        if not path:
            continue
        full_path = ".".join(path)
        field = next((candidate for candidate in field_labels if full_path.endswith(candidate)), None)
        if field is not None:
            display_label, unit = field_labels[field]
            display_value = value / 3600 if unit == "hours" and field.casefold().endswith("seconds") else value
            fields[display_label] = {"value": round(display_value, 2), "unit": unit}
    return {
        "label": label,
        "scope": scope,
        "available": bool(fields),
        "fields": fields,
        "unavailableReason": None if fields else "No readings returned for this date.",
    }


def _heart_zone_snapshot(payload: object) -> dict[str, Any]:
    """Return configured heart-rate zone boundaries without unrelated profile fields."""
    entries = []
    if isinstance(payload, list):
        for zone_set in payload:
            if not isinstance(zone_set, dict):
                continue
            sport = zone_set.get("sport")
            prefix = f"{sport} · " if isinstance(sport, str) and sport else ""
            for zone_number in range(1, 6):
                boundary = zone_set.get(f"zone{zone_number}Floor")
                if isinstance(boundary, (int, float)):
                    entries.append({"label": f"{prefix}Zone {zone_number}", "value": round(float(boundary)), "unit": "bpm"})
    return {
        "label": "Heart-rate zones",
        "scope": "Configured device zones",
        "available": bool(entries),
        "fields": entries,
        "unavailableReason": None if entries else "No heart-rate zones returned.",
    }


def _record_count_category(label: str, scope: str, payload: object, list_fields: tuple[str, ...]) -> dict[str, Any]:
    """Summarize a record-oriented health endpoint without exposing food or cycle details."""
    counts = {}
    if isinstance(payload, dict):
        for field in list_fields:
            value = payload.get(field)
            if isinstance(value, list):
                counts[field] = len(value)
    available = any(count > 0 for count in counts.values())
    return {
        "label": label,
        "scope": scope,
        "available": available,
        "fields": [{"label": name.replace("logged", "Logged ").replace("Details", " details").replace("WithServingSizes", ""), "value": count, "unit": "records"} for name, count in counts.items()],
        "unavailableReason": None if available else "No records returned for this date.",
    }


def _category_available(label: str, scope: str, payload: object) -> dict[str, Any]:
    """Show whether an optional health endpoint returned any data, without leaking its payload."""
    available = payload is not None and payload != {} and payload != []
    return {
        "label": label,
        "scope": scope,
        "available": available,
        "fields": [],
        "unavailableReason": None if available else "No data returned for this date.",
    }


def fetch_additional_health_data(
    client: GarminPersonalApiClient,
    start_date: date,
    end_date: date,
) -> list[dict[str, Any]]:
    """Fetch remaining documented personal health categories with per-category failure isolation."""
    latest_day = end_date
    endpoints = (
        ("sleep_details", "Detailed sleep", "Latest night", lambda: client.get_daily_sleep(latest_day)),
        ("heart_rate_detail", "Heart-rate detail", "Latest day", lambda: client.get_daily_heart_rate(latest_day)),
        ("spo2", "Blood oxygen", "Latest day", lambda: client.get_daily_spo2(latest_day)),
        ("fitness_age", "Fitness age", "Latest available", lambda: client.get_fitness_age(latest_day)),
        ("heart_rate_zones", "Heart-rate zones", "Configured zones", lambda: client.get_heart_rate_zones()),
        ("weight", "Weight and body composition", "Selected period", lambda: client.get_weight_measurements(start_date, end_date)),
        ("weight_goals", "Weight goals", "Selected period", lambda: client.get_effective_weight_goals(start_date, end_date)),
        ("nutrition", "Food log", "Latest day", lambda: client.get_daily_food_logs(latest_day)),
        ("cycle_summary", "Women’s health summary", "Latest day", lambda: client.get_menstrual_cycle_summary(latest_day)),
        ("cycle_detail", "Women’s health detail", "Latest day", lambda: client.get_menstrual_cycle_day_view(latest_day, latest_day)),
        ("wellness_activity", "Wellness activity summaries", "Selected period", lambda: client.get_wellness_activity_summaries(start_date, end_date)),
    )
    categories = []
    for key, label, scope, request in endpoints:
        try:
            payload = request()
        except Exception:
            payload = None

        if key == "spo2":
            categories.append(_numeric_snapshot(label, scope, payload, {
                "averageSpO2": ("Daily average", "%"),
                "lowestSpO2": ("Lowest reading", "%"),
                "lastSevenDaysAvgSpO2": ("7-day average", "%"),
                "latestSpO2": ("Latest reading", "%"),
                "avgSleepSpO2": ("Sleep average", "%"),
            }))
        elif key == "sleep_details":
            categories.append(_numeric_snapshot(label, scope, payload, {
                "sleepTimeSeconds": ("Total sleep", "hours"),
                "napTimeSeconds": ("Nap duration", "hours"),
                "deepSleepSeconds": ("Deep sleep", "hours"),
                "lightSleepSeconds": ("Light sleep", "hours"),
                "remSleepSeconds": ("REM sleep", "hours"),
                "awakeSleepSeconds": ("Awake during sleep", "hours"),
                "sleepScores.overall.value": ("Sleep score", "score"),
                "awakeCount": ("Awakenings", "events"),
                "avgSleepStress": ("Sleep stress", "score"),
                "averageRespirationValue": ("Sleep respiration", "breaths/min"),
                "avgHeartRate": ("Sleep heart rate", "bpm"),
            }))
        elif key == "heart_rate_detail":
            categories.append(_numeric_snapshot(label, scope, payload, {
                "restingHeartRate": ("Resting heart rate", "bpm"),
                "lastSevenDaysAvgRestingHeartRate": ("7-day resting heart-rate average", "bpm"),
                "minHeartRate": ("Minimum heart rate", "bpm"),
                "maxHeartRate": ("Maximum heart rate", "bpm"),
            }))
        elif key == "fitness_age":
            categories.append(_numeric_snapshot(label, scope, payload, {
                "fitnessAge": ("Fitness age", "years"),
                "achievableFitnessAge": ("Achievable fitness age", "years"),
                "previousFitnessAge": ("Previous fitness age", "years"),
                "chronologicalAge": ("Chronological age", "years"),
            }))
        elif key == "heart_rate_zones":
            categories.append(_heart_zone_snapshot(payload))
        elif key == "weight":
            categories.append(_numeric_snapshot(label, scope, payload, {
                "weight": ("Weight", "Garmin units"),
                "bmi": ("BMI", "index"),
                "bodyFat": ("Body fat", "%"),
                "bodyWater": ("Body water", "%"),
                "muscleMass": ("Muscle mass", "Garmin units"),
                "boneMass": ("Bone mass", "Garmin units"),
                "visceralFat": ("Visceral fat", "Garmin units"),
                "metabolicAge": ("Metabolic age", "years"),
            }))
        elif key == "nutrition":
            categories.append(_record_count_category(label, scope, payload, ("mealDetails", "loggedFoodsWithServingSizes")))
        elif key in {"cycle_summary", "cycle_detail"}:
            categories.append(_category_available(label, scope, payload))
        elif key == "wellness_activity":
            count = len(payload) if isinstance(payload, list) else 0
            categories.append({
                "label": label,
                "scope": scope,
                "available": count > 0,
                "fields": [{"label": "Summaries returned", "value": count, "unit": "records"}] if count else [],
                "unavailableReason": None if count else "No records returned for this period.",
            })
        elif key == "weight_goals":
            categories.append(_category_available(label, scope, payload))
        else:
            categories.append(_numeric_snapshot(label, scope, payload, {}))
    return categories


def fetch_dashboard_data(days: int) -> dict[str, Any]:
    """Fetch the supported health metrics for the user's own Garmin account."""
    if days < 1 or days > 90:
        raise ValueError("days must be between 1 and 90")
    api_key = _load_api_key()
    if not api_key:
        raise RuntimeError("A Garmin Personal API key is not configured")

    end_date = date.today()
    start_date = end_date - timedelta(days=days - 1)
    source_keys = list(METRIC_SOURCES.values())
    activity_start = end_date - timedelta(days=34)
    with PersonalApiAuthenticator() as authenticator:
        token = authenticator.obtain_token(api_key)
    raw_payloads: dict[str, object] = {}
    with GarminPersonalApiClient(token.access_token) as client:
        datasets, failures = _fetch_datasets(client, source_keys, start_date, end_date, raw_payloads)
        try:
            activity_records = _fetch_activity_records(client, activity_start, end_date)
            training_context = build_training_context(activity_records, end_date)
        except Exception:
            training_context = _empty_training_context()
    return build_dashboard_payload(
        datasets,
        failures,
        start_date,
        end_date,
        training_context,
        raw_payloads.get("hrv"),
    )


def main() -> int:
    """Fetch dashboard data and write one JSON document to standard output."""
    parser = argparse.ArgumentParser(description="Fetch personal Garmin health metrics as JSON.")
    parser.add_argument("--days", type=int, default=30)
    args = parser.parse_args()
    try:
        payload = fetch_dashboard_data(args.days)
    except Exception as error:
        print(f"Could not load Garmin health data ({type(error).__name__}).", file=sys.stderr)
        return 1
    json.dump(payload, sys.stdout, separators=(",", ":"))
    print()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())